mapper.update:
UPDATE students 
SET total_point = total_point + #{amount}
WHERE student_id = #{studentId} OR CAST(id AS CHAR) = #{studentId}

mapper.delete:
DELETE FROM get_points
WHERE student_id = (SELECT id FROM students WHERE student_id = #{studentId} OR CAST(id AS CHAR) = #{studentId} LIMIT 1)
   OR student_id = #{studentId}
